def parse_config(raw: dict) -> dict:
    if not isinstance(raw, dict):
        raise TypeError("config must be a dictionary")

    return {
        "debug": bool(raw.get("debug", False)),
        "page_size": _parse_page_size(raw.get("page_size", 25)),
        "features": _parse_features(raw.get("features", [])),
    }


def _parse_page_size(value) -> int:
    page_size = int(value)
    if not 1 <= page_size <= 100:
        raise ValueError("page_size must be between 1 and 100")
    return page_size


def _parse_features(value) -> list[str]:
    if isinstance(value, str):
        return [value]
    if isinstance(value, list):
        return [str(item) for item in value]
    raise ValueError("features must be a string or list")

